<?php
require_once __DIR__.'/../config/bootstrap.php';$pageTitle='Gerar frete';
$carriers=$pdo->query('SELECT id,name FROM carriers ORDER BY name')->fetchAll();$addresses=$pdo->query('SELECT id,label,city,state FROM addresses ORDER BY label')->fetchAll();$products=$pdo->query('SELECT id,name,quantity FROM products ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$productIds=$_POST['product_id']??[];$quantities=$_POST['product_quantity']??[];$valid=[];foreach($productIds as $i=>$pid){$pid=(int)$pid;$qty=(int)($quantities[$i]??1);if($pid>0&&$qty>0)$valid[$pid]=$qty;}
if(!post('carrier_id')||!post('origin_id')||!post('destination_id')||!post('freight_date')||!$valid){flash('danger','Preencha os dados do frete e adicione ao menos um produto.');}
else {try{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO freights(carrier_id,origin_id,destination_id,freight_date,status,notes) VALUES(?,?,?,?,?,?)');$s->execute([(int)post('carrier_id'),(int)post('origin_id'),(int)post('destination_id'),post('freight_date'),post('status','Pendente'),post('notes')]);$fid=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO freight_products(freight_id,product_id,quantity) VALUES(?,?,?)');foreach($valid as $pid=>$qty)$ins->execute([$fid,$pid,$qty]);$pdo->commit();flash('success','Frete #'.$fid.' gerado com sucesso.');redirect('freights/show.php?id='.$fid);}catch(Throwable $e){$pdo->rollBack();flash('danger','Não foi possível gerar o frete. Confira os dados selecionados.');}}}
require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><span class="eyebrow">OPERAÇÕES</span><h1>Gerar novo frete</h1><p>Relacione transportador, endereços e um ou mais produtos.</p></div></div>
<?php if(!$carriers||count($addresses)<2||!$products):?><div class="alert alert-warning">Para gerar fretes, cadastre ao menos um transportador, dois endereços e um produto.</div><?php endif;?>
<form method="post" class="form-panel"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><h2 class="section-title">Dados da operação</h2><div class="row g-3">
<div class="col-md-6"><label class="form-label">Transportador *</label><select class="form-select" name="carrier_id" required><option value="">Selecione</option><?php foreach($carriers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div>
<div class="col-md-6"><label class="form-label">Data do frete *</label><input class="form-control" type="date" name="freight_date" required value="<?=date('Y-m-d')?>"></div>
<div class="col-md-6"><label class="form-label">Endereço de origem *</label><select class="form-select" name="origin_id" required><option value="">Selecione</option><?php foreach($addresses as $a):?><option value="<?=$a['id']?>"><?=e($a['label'].' — '.$a['city'].'/'.$a['state'])?></option><?php endforeach;?></select></div>
<div class="col-md-6"><label class="form-label">Endereço de destino *</label><select class="form-select" name="destination_id" required><option value="">Selecione</option><?php foreach($addresses as $a):?><option value="<?=$a['id']?>"><?=e($a['label'].' — '.$a['city'].'/'.$a['state'])?></option><?php endforeach;?></select></div>
<div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['Pendente','Em trânsito','Entregue','Cancelado'] as $st):?><option><?=e($st)?></option><?php endforeach;?></select></div>
<div class="col-12"><label class="form-label">Observações</label><textarea class="form-control" name="notes" rows="2"></textarea></div></div>
<hr class="my-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="section-title mb-0">Produtos do frete</h2><button type="button" class="btn btn-light btn-sm" data-add-product>＋ Adicionar produto</button></div>
<div data-products><?php for($i=0;$i<1;$i++):?><div class="product-row"><select class="form-select" name="product_id[]" required><option value="">Selecione um produto</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> (estoque: <?=$p['quantity']?>)</option><?php endforeach;?></select><input class="form-control" type="number" name="product_quantity[]" min="1" value="1" required><button class="remove-row" type="button" data-remove-product>×</button></div><?php endfor;?></div>
<div class="form-actions"><button class="btn btn-primary" <?=(!$carriers||count($addresses)<2||!$products)?'disabled':''?>>Gerar frete</button><a class="btn btn-light" href="<?=e(url('freights/index.php'))?>">Cancelar</a></div></form><?php require __DIR__.'/../includes/footer.php';?>
